void positions(const Orders *orders, int *out) {
    for (int i = 0; i < orders->count; ++i)
        for (int j = 0; j < orders->rows[i].count; ++j)
            out[orders->rows[i].data[j]] = j;
}
typedef struct {
    int upper, lower;
} PositionPair;
static int compare_pairs(const void *left, const void *right) {
    const PositionPair *a = left, *b = right;
    if (a->upper != b->upper)
        return (a->upper > b->upper) - (a->upper < b->upper);
    return (a->lower > b->lower) - (a->lower < b->lower);
}
int gap_crossings(const Segment *segments, const IntList *indices, const int *pos, int width) {
    PositionPair pairs[120];
    for (int i = 0; i < indices->count; ++i) {
        const Segment *segment = &segments[indices->data[i]];
        pairs[i] = (PositionPair){pos[segment->upper], pos[segment->lower]};
    }
    if (indices->count > 1)
        qsort(pairs, (size_t)indices->count, sizeof *pairs, compare_pairs);
    int capacity = 1;
    while (capacity < width)
        capacity *= 2;
    int tree[2047] = {0}, out = 0;
    for (int i = 0; i < indices->count; ++i) {
        int at = pairs[i].lower + capacity - 1;
        ++tree[at];
        while (at) {
            if (at % 2)
                out += tree[at + 1];
            at = (at - 1) / 2;
            ++tree[at];
        }
    }
    return out;
}
int total_crossings(const Layout *layout, const Orders *orders) {
    int pos[600] = {0}, out = 0;
    positions(orders, pos);
    for (int i = 0; i < layout->gaps.count; ++i)
        out +=
            gap_crossings(layout->segments, &layout->gaps.rows[i], pos, orders->rows[i + 1].count);
    return out;
}
int brute_crossings(Layout *layout, const Orders *orders, bool count_edges) {
    int pos[600] = {0}, out = 0;
    positions(orders, pos);
    for (int gap = 0; gap < layout->gaps.count; ++gap) {
        const IntList *indices = &layout->gaps.rows[gap];
        for (int i = 0; i < indices->count; ++i)
            for (int j = i + 1; j < indices->count; ++j) {
                const Segment *a = &layout->segments[indices->data[i]],
                              *b = &layout->segments[indices->data[j]];
                if ((pos[a->upper] - pos[b->upper]) * (pos[a->lower] - pos[b->lower]) < 0) {
                    ++out;
                    if (count_edges) {
                        ++layout->edges[a->edge].crossings;
                        ++layout->edges[b->edge].crossings;
                    }
                }
            }
    }
    return out;
}
int adjacent_cost(const Layout *layout, int left, int right, const int *pos) {
    int out = 0;
    const Vertex *a = &layout->vertices[left], *b = &layout->vertices[right];
    for (int i = 0; i < a->upper.count; ++i)
        for (int j = 0; j < b->upper.count; ++j)
            if (pos[a->upper.data[i]] > pos[b->upper.data[j]])
                ++out;
    for (int i = 0; i < a->lower.count; ++i)
        for (int j = 0; j < b->lower.count; ++j)
            if (pos[a->lower.data[i]] > pos[b->lower.data[j]])
                ++out;
    return out;
}
Coordinates coordinates(Layout *layout) {
    Coordinates out = {0};
    int count = layout->vertex_count, pos[600] = {0};
    positions(&layout->orders, pos);
    int minimum = 0;
    for (int v = 0; v < count; ++v) {
        int values[4];
        for (int i = 0; i < 4; ++i)
            values[i] = out.variants[i].aligned[v];
        qsort(values, 4, sizeof *values, compare_ints);
        layout->vertices[v].x = floor_div(values[1] + values[2], 2);
        int low = layout->vertices[v].x - layout->vertices[v].left;
        if (!v || low < minimum)
            minimum = low;
    }
    for (int v = 0; v < count; ++v)
        layout->vertices[v].x -= minimum;
    return out;
}
Canvas canvas_create(int main_length, int secondary_length, Direction direction) {
    Canvas out = {main_length,
                  secondary_length,
                  vertical(direction) ? main_length : secondary_length,
                  vertical(direction) ? secondary_length : main_length,
                  direction,
                  NULL};
    out.cells = allocate((size_t)out.rows * (size_t)out.columns * sizeof *out.cells);
    return out;
}
Cell canvas_map(const Canvas *canvas, int main, int secondary) {
    if (canvas->direction == DIR_BT || canvas->direction == DIR_RL)
        main = canvas->main_length - 1 - main;
    return vertical(canvas->direction) ? (Cell){main, secondary} : (Cell){secondary, main};
}
Pixel *canvas_at(Canvas *canvas, Cell cell) {
    return &canvas->cells[(size_t)cell.row * (size_t)canvas->columns + (size_t)cell.column];
static const Pixel *canvas_get(const Canvas *canvas, Cell cell) {
    return &canvas->cells[(size_t)cell.row * (size_t)canvas->columns + (size_t)cell.column];
}
void canvas_line(Canvas *canvas, int main, int secondary, unsigned char kind) {
    canvas_at(canvas, canvas_map(canvas, main, secondary))->lines |= kind;
}
void canvas_main_line(Canvas *canvas, int main, int secondary) {
    canvas_line(canvas, main, secondary, vertical(canvas->direction) ? 1 : 2);
}
static void secondary_line(Canvas *canvas, int main, int secondary) {
    canvas_line(canvas, main, secondary, vertical(canvas->direction) ? 2 : 1);
}
void canvas_segment(Canvas *canvas, int start, int gap, int upper, int lower, int offset) {
    if (upper == lower) {
        for (int i = 0; i < gap; ++i)
            canvas_main_line(canvas, start + i, upper);
        return;
    }
    for (int i = 0; i < offset; ++i)
        canvas_main_line(canvas, start + i, upper);
    canvas_line(canvas, start + offset, upper, 4);
    canvas_line(canvas, start + offset, lower, 4);
    int low = upper < lower ? upper : lower, high = upper > lower ? upper : lower;
    for (int x = low + 1; x < high; ++x)
        secondary_line(canvas, start + offset, x);
    for (int i = offset + 1; i < gap; ++i)
        canvas_main_line(canvas, start + i, lower);
}
int canvas_crossing_cells(const Canvas *canvas) {
    int out = 0;
    for (int i = 0; i < canvas->rows * canvas->columns; ++i)
        if ((canvas->cells[i].lines & 3) == 3)
            ++out;
    return out;
}
static char character(const Canvas *canvas, Cell cell) {
    const Pixel *pixel = canvas_get(canvas, cell);
    if (pixel->box)
        return pixel->box;
    if (pixel->arrow)
        return pixel->arrow;
    if (pixel->highlighted)
        return '#';
    if (!pixel->lines)
        return ' ';
    if (pixel->lines == 1)
        return '|';
    if (pixel->lines == 2)
        return '-';
    return '+';
}
TextLines canvas_drawing(const Canvas *canvas, const char *name) {
    TextLines out = {0};
    lines_push(&out, format_text("graph %s %dx%d", name, canvas->columns, canvas->rows));
    char *ruler = allocate((size_t)canvas->columns + 5);
    memcpy(ruler, "    ", 4);
    for (int c = 0; c < canvas->columns; ++c)
        ruler[c + 4] = (char)('0' + c % 10);
    ruler[canvas->columns + 4] = 0;
    lines_push(&out, ruler);
    for (int r = 0; r < canvas->rows; ++r) {
        char *line = allocate((size_t)canvas->columns + 5);
        snprintf(line, 5, "%3d ", r);
        for (int c = 0; c < canvas->columns; ++c)
            line[c + 4] = character(canvas, (Cell){r, c});
        int length = canvas->columns + 4;
        while (length && line[length - 1] == ' ')
            --length;
        line[length] = 0;
        lines_push(&out, line);
    }
    return out;
}
